205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
208	        HttpHeaders headers = new HttpHeaders();
209	        Visit visit = visitMapper.toVisit(visitFieldsDto);
210	        Pet pet = new Pet();
211	        pet.setId(petId);
212	        visit.setPet(pet);
213	        this.clinicService.saveVisit(visit);
214	        VisitDto visitDto = visitMapper.toVisitDto(visit);
215	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
216	            .buildAndExpand(visit.getId()).toUri());
217	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
218	    }
